+/*
+ * Brand band (D12, D13): primary blue with a dark-blue line below and the decorative logo,
+ * aligned with the content container. It is `aria-hidden` and has no text.
+ */
+:host {
+  --brand-bar-height: 3.5rem;
+  --brand-line: 0.375rem;
+  position: relative;
+  display: block;
+  min-height: 100vh;
+}
+
+@media (min-width: 48rem) {
+  :host {
+    --brand-bar-height: 4.75rem;
+  }
+}
+
+.brand-bar {
+  border-bottom: var(--brand-line) solid var(--color-primary-dark);
+  background:
+    radial-gradient(
+      circle at calc(100% - 3rem) 150%,
+      rgb(255 255 255 / 0.12) 0 6rem,
+      transparent 6.05rem
+    ),
+    radial-gradient(
+      circle at calc(100% - 13rem) -110%,
+      rgb(255 255 255 / 0.08) 0 5rem,
+      transparent 5.05rem
+    ),
+    var(--color-primary);
+}
+
+.brand-bar-inner {
+  display: flex;
+  align-items: center;
+  max-width: var(--container-max);
+  height: var(--brand-bar-height);
+  margin: 0 auto;
+  padding: 0 var(--gutter);
+}
+
+.brand-logo {
+  display: block;
+  width: auto;
+  height: 1.875rem;
+}
+
+@media (min-width: 48rem) {
+  .brand-logo {
+    height: 2.75rem;
+  }
+}
+
+/*
+ * Global "cargando" while a navigation is pending (ADR-0004, G3-9). It overlays the brand band so
+ * the page does not jump: the visible text sits on the right of the band in a dark-blue pill
+ * (white on #0033A0, 10.6:1) and a yellow bar runs along the dark line. Hidden when empty.
+ */
 .global-loading:empty {
   display: none;
 }

 .global-loading {
-  padding: 0.5rem 1rem;
-  background: #eef3fd;
+  position: absolute;
+  inset: 0 0 auto;
+  height: calc(var(--brand-bar-height) + var(--brand-line));
+  overflow: hidden;
+  pointer-events: none;
+}
+
+.global-loading::after {
+  content: '';
+  position: absolute;
+  bottom: 0;
+  left: 0;
+  width: 35%;
+  height: var(--brand-line);
+  border-radius: var(--brand-line);
+  background: var(--color-accent);
+  animation: global-loading-bar 1.1s ease-in-out infinite;
+}
+
+.global-loading-inner {
+  display: flex;
+  align-items: center;
+  justify-content: flex-end;
+  max-width: var(--container-max);
+  height: var(--brand-bar-height);
+  margin: 0 auto;
+  padding: 0 var(--gutter);
+}
+
+.global-loading-label {
+  padding: 0.25rem 0.875rem;
+  border-radius: var(--radius-pill);
+  background: var(--color-primary-dark);
+  color: #ffffff;
+  font-size: 0.875rem;
+  font-weight: 600;
+}
+
+@keyframes global-loading-bar {
+  from {
+    transform: translateX(-100%);
+  }
+  to {
+    transform: translateX(300%);
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .global-loading::after {
+    width: 100%;
+    animation: none;
+  }
+}
+
+main {
+  padding-bottom: 4rem;
 }
