S="C:/Users/JORGEA~1/AppData/Local/Temp/claude/7c00b3cd46447d40/e47a27f0-74c7-4957-994a-94c086d65178/scratchpad"; R="C:/Users/Jorge Andres/Documents/_SURA/car-insurance-quote-multicountry/e2e"; mkdir -p "$S/probe"; cat > "$S/probe/probe.spec.ts" <<EOF
import { test, expect, goToCoPlans, CO } from '$R/support/fixtures';

test('probe hit testing and a11y name of plan cards', async ({ page }) => {
  await goToCoPlans(page);
  const li = page.locator('.plan').filter({ hasText: 'Plan Total' }).getByRole('listitem').filter({ hasText: 'Hurto' });
  const box = (await li.boundingBox())!;
  const hit = await page.evaluate(([x, y]) => {
    const el = document.elementFromPoint(x, y) as HTMLElement;
    return el.tagName + '.' + el.className + ' for=' + el.getAttribute('for');
  }, [box.x + box.width / 2, box.y + box.height / 2]);
  console.log('elementFromPoint(coverage "Hurto" of Plan Total) =', hit);
  const sel = await page.evaluate(() => getSelection()?.toString());
  console.log('radios:', JSON.stringify(await page.getByRole('radio').evaluateAll(rs => rs.map(r => (r as HTMLInputElement).labels?.[0]?.textContent?.replace(/\s+/g,' ').trim()))));
  console.log('aria snapshot plan group:\n' + await page.getByRole('group', { name: 'Planes disponibles' }).ariaSnapshot());
  const link = page.getByRole('link', { name: CO.texts.changeCountry });
  await link.focus();
  console.log('change-country :focus-visible outline =', await link.evaluate(a => { const s = getComputedStyle(a); return s.outlineStyle + ' ' + s.outlineWidth + ' ' + s.outlineColor + ' offset ' + s.outlineOffset; }));
  const radio = page.getByRole('radio').first();
  await page.keyboard.press('Tab'); await page.keyboard.press('Shift+Tab');
});

for (const w of [320, 1280]) {
  test('probe country selection at ' + w, async ({ page }) => {
    await page.setViewportSize({ width: w, height: 800 });
    await page.goto('/');
    const link = page.getByRole('link', { name: 'Colombia' });
    await expect(link).toBeVisible();
    const dims = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth }));
    console.log(w, 'country selection scrollWidth/clientWidth', JSON.stringify(dims));
    await page.keyboard.press('Tab');
    const focused = await page.evaluate(() => { const a = document.activeElement as HTMLElement; const s = getComputedStyle(a); return a.textContent?.trim() + ' | outline ' + s.outlineStyle + ' ' + s.outlineWidth + ' ' + s.outlineColor; });
    console.log(w, 'first Tab focus on / :', focused);
    const b = await link.boundingBox();
    console.log(w, 'Colombia card box', JSON.stringify(b));
    await page.goto('/co/form');
    const cc = page.getByRole('link', { name: CO.texts.changeCountry });
    await expect(cc).toBeVisible();
    console.log(w, 'change-country box', JSON.stringify(await cc.boundingBox()));
    const dims2 = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth }));
    console.log(w, '/co/form scrollWidth/clientWidth', JSON.stringify(dims2));
    await page.keyboard.press('Tab');
    console.log(w, 'first Tab on /co/form:', await page.evaluate(() => (document.activeElement as HTMLElement).outerHTML.slice(0, 90)));
  });
}
EOF
